<?php
/**
 * Plugin Name: {{TITLE}} internal license
 * Description: Activates {{TITLE}} with the internal API key defined in wp-config.php, so the site receives updates from {{API_HOST}} without a license key entered on screen and without license notices.
 * Version: {{TEMPLATE_VERSION}}
 * License: GPL-2.0-or-later
 *
 * Generated by the wc-am-internal-license skill. Regenerate it with the skill instead of editing this copy.
 *
 * Usage: copy this file to wp-content/mu-plugins/ on a site you run, then add to wp-config.php:
 *
 *     define( '{{KEY_CONSTANT}}', '<User license key (formerly Master API Key) of the internal account on {{API_HOST}}>' );
 *
 *   The constant is read once all mu-plugins have loaded, so where wp-config.php cannot be edited it can be
 *   defined in another mu-plugin instead.
 * - The bundled WooCommerce API Manager client (wc-am-client.php 2.x) reads a placeholder key, the activation
 *   status and the product ID through pre_option_ filters. The client puts the key in the query string of
 *   its request URLs, which debug tools, proxies and access logs may record, so it never gets the real key:
 *   its requests to {{API_HOST}} are sent again with the real key in the POST body and without following
 *   redirects. Only requests for this product ID at this API URL are taken, because a file generated for
 *   another product gives its client the same placeholder. The key and the product ID are never written to
 *   the database, and the client's license settings page is closed, so the key never shows on screen.
 * - On an administrator's admin page load, the site is activated on {{API_HOST}} when the key, product ID,
 *   instance or site address differs from the last successful activation, and the activation is checked
 *   once a day (the store drops it when the license expires, the subscription goes on hold, or it is removed
 *   from My Account). When the store cannot be reached for that check, the activation is kept and checked again
 *   after an hour. A failure is retried after an hour, or at once when the key, product ID, instance or site
 *   address changes, and is shown on the Plugins and Updates screens only.
 * - Without the constant (or with a malformed key) this file does nothing, and the plugin behaves like any
 *   other unlicensed site.
 * - Removing this file does not deactivate the site on {{API_HOST}}. Remove the activation from
 *   My Account > API Keys there.
 * - Multisite is not supported: on a multisite install this file does nothing.
 *
 * @package {{PACKAGE}}
 */

defined( 'ABSPATH' ) || exit;

if ( ! class_exists( 'AW_WC_AM_Internal_License_{{CLASS_VERSION}}' ) ) {
	/**
	 * Feeds an internal API key to a bundled WooCommerce API Manager client.
	 *
	 * The class name carries the template version, so files generated from different templates can run
	 * side by side on one site.
	 */
	final class AW_WC_AM_Internal_License_{{CLASS_VERSION}} {

		/**
		 * Seconds to wait before retrying a failed activation.
		 */
		const RETRY_AFTER = 3600;

		/**
		 * Seconds after which a successful activation is checked again with a status request.
		 */
		const RECHECK_AFTER = 86400;

		/**
		 * Key the client is given instead of the real one. If it ever reached the store, it would only fail.
		 */
		const PLACEHOLDER_KEY = 'internal-license-mu-plugin';

		/**
		 * Plugin basename, e.g. "my-plugin/my-plugin.php".
		 *
		 * @var string
		 */
		private $plugin_file;

		/**
		 * Product name shown on the Plugins screen.
		 *
		 * @var string
		 */
		private $title;

		/**
		 * API Manager product ID of the internal order.
		 *
		 * @var int
		 */
		private $product_id;

		/**
		 * Root URL of the store running the API Manager, with a trailing slash.
		 *
		 * @var string
		 */
		private $api_url;

		/**
		 * Name of the wp-config.php constant holding the API key.
		 *
		 * @var string
		 */
		private $key_constant;

		/**
		 * Option the client keeps its data in: "wc_am_client_" plus the product ID, or the plugin slug when the
		 * plugin passes no product ID to the client.
		 *
		 * @var string
		 */
		private $data_key;

		/**
		 * Option the client reads the product ID from when the plugin passes none; empty otherwise.
		 *
		 * @var string
		 */
		private $product_id_option;

		/**
		 * Menu slug of the client's license settings page.
		 *
		 * @var string
		 */
		private $settings_page;

		/**
		 * Option holding this file's activation record.
		 *
		 * @var string
		 */
		private $state_option;

		/**
		 * Constructor.
		 *
		 * @param array{plugin_file: string, title: string, product_id: int, client_has_product_id: bool, api_url: string, key_constant: string, settings_page: string} $config Settings written by the skill.
		 */
		public function __construct( array $config ) {
			$this->plugin_file  = $config['plugin_file'];
			$this->title        = $config['title'];
			$this->product_id   = (int) $config['product_id'];
			$this->api_url      = trailingslashit( $config['api_url'] );
			$this->key_constant = $config['key_constant'];

			// Same naming as the client's constructor.
			$slug = self::normalize( dirname( $this->plugin_file ) );

			$this->data_key          = 'wc_am_client_' . ( $config['client_has_product_id'] ? self::normalize( (string) $this->product_id ) : $slug );
			$this->product_id_option = $config['client_has_product_id'] ? '' : 'wc_am_product_id_' . $slug;
			$this->settings_page     = '' !== $config['settings_page'] ? $config['settings_page'] : $this->data_key . '_dashboard';
			$this->state_option      = $this->data_key . '_internal_license';
		}

		/**
		 * Registers the hooks once all mu-plugins have loaded, so the constant may come from any of them.
		 * The client is created on init, which is later still.
		 *
		 * @return void
		 */
		public function register() {
			if ( did_action( 'muplugins_loaded' ) ) {
				$this->boot();
				return;
			}
			add_action( 'muplugins_loaded', array( $this, 'boot' ) );
		}

		/**
		 * Adds the filters and actions. Does nothing without a well-formed key, with a non-https API URL, or on
		 * multisite, where the client's options are per site but update data is network-wide.
		 *
		 * @return void
		 */
		public function boot() {
			if ( is_multisite() || '' === $this->api_key() || 'https' !== wp_parse_url( $this->api_url, PHP_URL_SCHEME ) ) {
				return;
			}

			add_filter( 'pre_option_' . $this->data_key, array( $this, 'client_data' ) );
			add_filter( 'pre_update_option_' . $this->data_key, array( $this, 'keep_stored_value' ), 10, 2 );
			add_filter( 'pre_option_' . $this->data_key . '_activated', array( $this, 'activated' ) );
			// Early, so the client's request is answered before anything else sends or answers it.
			add_filter( 'pre_http_request', array( $this, 'send_client_request' ), 1, 3 );

			if ( '' !== $this->product_id_option ) {
				add_filter( 'pre_option_' . $this->product_id_option, array( $this, 'product_id' ) );
				add_filter( 'pre_update_option_' . $this->product_id_option, array( $this, 'keep_stored_value' ), 10, 2 );
			}

			add_action( 'admin_init', array( $this, 'close_settings_page' ), 1 );
			// After the client's own admin_init callback, which creates the instance ID.
			add_action( 'admin_init', array( $this, 'maybe_activate' ), 20 );
			add_action( 'admin_menu', array( $this, 'remove_settings_menu' ), 99 );
			add_action( 'admin_notices', array( $this, 'activation_error_notice' ) );
			add_filter( 'plugin_row_meta', array( $this, 'row_meta' ), 10, 2 );
		}

		/**
		 * Returns the client's data option with the placeholder key. send_client_request() puts the real key in.
		 *
		 * @return array<string, string>
		 */
		public function client_data() {
			return array( $this->data_key . '_api_key' => self::PLACEHOLDER_KEY );
		}

		/**
		 * Sends a request of the client's to the API Manager again, with the real key in the POST body instead of
		 * the placeholder in the URL, and without following redirects.
		 *
		 * @param false|array<string, mixed>|WP_Error $preempt Response to use instead of a request.
		 * @param array<string, mixed>|mixed          $args    Request arguments.
		 * @param string|mixed                        $url     Request URL.
		 * @return false|array<string, mixed>|WP_Error
		 */
		public function send_client_request( $preempt, $args, $url ) {
			if ( false !== $preempt || ! is_array( $args ) || ! is_string( $url ) || ! $this->is_api_endpoint( $url ) ) {
				return $preempt;
			}

			// A file generated for another product on the same store gives its client the same placeholder.
			parse_str( (string) wp_parse_url( $url, PHP_URL_QUERY ), $query );
			if ( ! isset( $query['wc-api'], $query['api_key'], $query['product_id'] ) || 'wc-am-api' !== $query['wc-api'] || self::PLACEHOLDER_KEY !== $query['api_key'] || (string) $this->product_id !== $query['product_id'] ) {
				return $preempt;
			}

			unset( $query['wc-api'], $args['_redirection'] );
			$query['api_key'] = $this->api_key();

			$args['method']      = 'POST';
			$args['body']        = array_merge( is_array( $args['body'] ?? null ) ? $args['body'] : array(), $query );
			$args['redirection'] = 0;

			return wp_safe_remote_request( add_query_arg( 'wc-api', 'wc-am-api', $this->api_url ), $args );
		}

		/**
		 * Tells whether a URL points at this file's API Manager: the same host and path, with or without the
		 * trailing slash (the client keeps the API URL as the plugin passes it).
		 *
		 * @param string $url Request URL.
		 * @return bool
		 */
		private function is_api_endpoint( $url ) {
			$target = wp_parse_url( $url );
			$store  = wp_parse_url( $this->api_url );

			return isset( $target['host'], $store['host'] ) && $target['host'] === $store['host']
				&& untrailingslashit( $target['path'] ?? '' ) === untrailingslashit( $store['path'] ?? '' );
		}

		/**
		 * Reports the client as activated, so it shows no inactive notice.
		 *
		 * @return string
		 */
		public function activated() {
			return 'Activated';
		}

		/**
		 * Returns the product ID the client sends to the API Manager.
		 *
		 * @return int
		 */
		public function product_id() {
			return $this->product_id;
		}

		/**
		 * Stops the client from writing an option this file supplies (and the key with it).
		 *
		 * @param mixed $value     New value.
		 * @param mixed $old_value Current value, which is this file's.
		 * @return mixed
		 */
		public function keep_stored_value( $value, $old_value ) {
			return $old_value;
		}

		/**
		 * Sends the client's license settings page back to the Plugins screen, because its key field would show
		 * the key from the constant.
		 *
		 * @return void
		 */
		public function close_settings_page() {
			global $plugin_page;

			if ( isset( $plugin_page ) && $this->settings_page === $plugin_page ) {
				wp_safe_redirect( admin_url( 'plugins.php' ) );
				exit;
			}
		}

		/**
		 * Removes the client's license settings page from the admin menu, wherever the client added it.
		 *
		 * @return void
		 */
		public function remove_settings_menu() {
			global $submenu;

			foreach ( array_keys( (array) $submenu ) as $parent ) {
				remove_submenu_page( $parent, $this->settings_page );
			}
			remove_menu_page( $this->settings_page );
		}

		/**
		 * Activates the site on the API Manager when the last activation does not match the current settings, or
		 * when the daily check finds that the store no longer has it.
		 *
		 * Runs for administrators only: admin_init also fires for logged-out requests to admin-post.php.
		 *
		 * @return void
		 */
		public function maybe_activate() {
			if ( wp_doing_ajax() || ! current_user_can( 'manage_options' ) || ! function_exists( 'is_plugin_active' ) || ! is_plugin_active( $this->plugin_file ) ) {
				return;
			}

			$instance = get_option( $this->data_key . '_instance' );
			if ( ! is_string( $instance ) || '' === $instance ) {
				return;
			}

			$site        = $this->site_object();
			$fingerprint = hash_hmac( 'sha256', implode( '|', array( $this->api_key(), (string) $this->product_id, $instance, $site ) ), wp_salt( 'auth' ) );
			$state       = $this->state();
			$matches     = hash_equals( $state['fingerprint'], $fingerprint );

			// The retry wait holds the fingerprint it was set for, so a changed key or site is tried at once.
			if ( ( $matches && time() - $state['checked_at'] < self::RECHECK_AFTER ) || get_transient( $this->state_option . '_retry' ) === $fingerprint ) {
				return;
			}

			if ( $matches ) {
				$active = $this->is_active( $instance, $site );
				if ( true === $active ) {
					$state['checked_at'] = time();
					update_option( $this->state_option, $state );
					return;
				}
				if ( null === $active ) {
					// The store could not be asked: keep the activation and ask again after the retry wait.
					set_transient( $this->state_option . '_retry', $fingerprint, self::RETRY_AFTER );
					return;
				}
			}

			$error = $this->activate( $instance, $site );

			if ( '' === $error ) {
				update_option(
					$this->state_option,
					array(
						'fingerprint'  => $fingerprint,
						'activated_at' => time(),
						'checked_at'   => time(),
						'error'        => '',
						'failed_at'    => 0,
					)
				);
				delete_transient( $this->state_option . '_retry' );
				// The cached update check was made without an activation, so it has no package.
				delete_site_transient( 'update_plugins' );
				return;
			}

			// Not activated any more, whatever the last success was: the next try activates again.
			$state['fingerprint'] = '';
			$state['error']       = $error;
			$state['failed_at']   = time();
			update_option( $this->state_option, $state );
			set_transient( $this->state_option . '_retry', $fingerprint, self::RETRY_AFTER );
		}

		/**
		 * Shows why the last activation failed, on the Plugins and Updates screens only.
		 *
		 * @return void
		 */
		public function activation_error_notice() {
			if ( ! current_user_can( 'manage_options' ) || ! function_exists( 'get_current_screen' ) ) {
				return;
			}

			$screen = get_current_screen();
			if ( null === $screen || ! in_array( $screen->id, array( 'plugins', 'update-core' ), true ) ) {
				return;
			}

			$state = $this->state();
			if ( '' === $state['error'] ) {
				return;
			}

			printf(
				'<div class="notice notice-warning"><p>%s</p></div>',
				esc_html(
					sprintf(
						'%1$s: the internal license could not be activated on %2$s, so updates do not arrive. It is retried after an hour. Response: %3$s',
						$this->title,
						(string) wp_parse_url( $this->api_url, PHP_URL_HOST ),
						$state['error']
					)
				)
			);
		}

		/**
		 * Notes on the Plugins screen that this file licenses the plugin.
		 *
		 * @param array<int|string, string>|mixed $links Row meta links.
		 * @param string|mixed                    $file  Plugin basename of the row.
		 * @return array<int|string, string>|mixed
		 */
		public function row_meta( $links, $file ) {
			if ( ! is_array( $links ) || $this->plugin_file !== $file || ! current_user_can( 'manage_options' ) ) {
				return $links;
			}

			$state   = $this->state();
			$links[] = esc_html(
				'' !== $state['fingerprint']
					? 'Licensed with the internal key (mu-plugin)'
					: 'Internal key (mu-plugin): not activated yet'
			);

			return $links;
		}

		/**
		 * Returns the key from the constant, or '' when it is missing or malformed.
		 *
		 * @return string
		 */
		private function api_key() {
			if ( ! defined( $this->key_constant ) ) {
				return '';
			}

			$key = constant( $this->key_constant );
			if ( ! is_string( $key ) ) {
				return '';
			}

			$key = trim( $key );

			return 1 === preg_match( '/^[A-Za-z0-9_-]{1,190}\z/', $key ) ? $key : '';
		}

		/**
		 * Activates this instance. An instance the server already activated is checked with a status request,
		 * since the server refuses to activate it twice.
		 *
		 * @param string $instance Instance ID the client created.
		 * @param string $site     Site address without the scheme.
		 * @return string '' on success, otherwise the reason.
		 */
		private function activate( $instance, $site ) {
			$response = $this->request(
				array(
					'wc_am_action'     => 'activate',
					'instance'         => $instance,
					'object'           => $site,
					'software_version' => $this->plugin_version(),
				)
			);

			if ( ! is_array( $response ) ) {
				return $response;
			}
			if ( isset( $response['success'], $response['activated'] ) && true === $response['success'] && true === $response['activated'] ) {
				return '';
			}

			return true === $this->is_active( $instance, $site ) ? '' : $this->error_message( $response );
		}

		/**
		 * Asks the API Manager whether this instance is activated.
		 *
		 * @param string $instance Instance ID the client created.
		 * @param string $site     Site address without the scheme.
		 * @return bool|null Null when the store could not be asked (the request failed, the status was not 200,
		 *                   or the response was not JSON).
		 */
		private function is_active( $instance, $site ) {
			$status = $this->request(
				array(
					'wc_am_action' => 'status',
					'instance'     => $instance,
					'object'       => $site,
				)
			);

			if ( ! is_array( $status ) ) {
				return null;
			}

			return isset( $status['success'], $status['data']['activated'] ) && true === $status['success'] && true === $status['data']['activated'];
		}

		/**
		 * Sends a request to the API Manager. The key goes in the POST body, and redirects are not followed so
		 * the key is not carried to another host.
		 *
		 * @param array<string, string> $args Request parameters besides the key and the product ID.
		 * @return array<mixed>|string Decoded response, or the reason it failed.
		 */
		private function request( array $args ) {
			$response = wp_safe_remote_post(
				add_query_arg( 'wc-api', 'wc-am-api', $this->api_url ),
				array(
					'timeout'     => 15,
					'redirection' => 0,
					'body'        => array_merge(
						array(
							'api_key'    => $this->api_key(),
							'product_id' => (string) $this->product_id,
						),
						$args
					),
				)
			);

			if ( is_wp_error( $response ) ) {
				return self::clean( $response->get_error_message() );
			}

			$code = (int) wp_remote_retrieve_response_code( $response );
			if ( 200 !== $code ) {
				return 'HTTP ' . $code;
			}

			$body = json_decode( wp_remote_retrieve_body( $response ), true );

			return is_array( $body ) ? $body : 'The response was not JSON.';
		}

		/**
		 * Picks the error message out of an API Manager response.
		 *
		 * @param array<mixed> $response Decoded response.
		 * @return string
		 */
		private function error_message( array $response ) {
			foreach ( array( $response['data']['error'] ?? null, $response['error'] ?? null ) as $message ) {
				if ( is_string( $message ) && '' !== trim( $message ) ) {
					return self::clean( $message );
				}
			}

			return 'The server did not activate the site.';
		}

		/**
		 * Returns this file's activation record.
		 *
		 * @return array{fingerprint: string, activated_at: int, checked_at: int, error: string, failed_at: int}
		 */
		private function state() {
			$state = get_option( $this->state_option );
			$state = is_array( $state ) ? $state : array();

			return array(
				'fingerprint'  => isset( $state['fingerprint'] ) && is_string( $state['fingerprint'] ) ? $state['fingerprint'] : '',
				'activated_at' => isset( $state['activated_at'] ) ? (int) $state['activated_at'] : 0,
				'checked_at'   => isset( $state['checked_at'] ) ? (int) $state['checked_at'] : 0,
				'error'        => isset( $state['error'] ) && is_string( $state['error'] ) ? $state['error'] : '',
				'failed_at'    => isset( $state['failed_at'] ) ? (int) $state['failed_at'] : 0,
			);
		}

		/**
		 * Returns the site address the way the client sends it.
		 *
		 * @return string
		 */
		private function site_object() {
			return str_ireplace( array( 'http://', 'https://' ), '', home_url() );
		}

		/**
		 * Returns the installed plugin's version from its header.
		 *
		 * @return string
		 */
		private function plugin_version() {
			$data = get_file_data( WP_PLUGIN_DIR . '/' . $this->plugin_file, array( 'version' => 'Version' ) );

			return $data['version'];
		}

		/**
		 * Normalizes a product ID or slug the way the client builds its option names.
		 *
		 * @param string $value Product ID or slug.
		 * @return string
		 */
		private static function normalize( $value ) {
			return strtolower( str_ireplace( array( ' ', '_', '&', '?', '-' ), '_', $value ) );
		}

		/**
		 * Strips markup and shortens a message from the network before it is stored. Never returns '', which
		 * the callers take for success.
		 *
		 * @param string $message Message.
		 * @return string
		 */
		private static function clean( $message ) {
			$message = mb_substr( trim( wp_strip_all_tags( $message ) ), 0, 300 );

			return '' === $message ? 'The request failed without a reason.' : $message;
		}
	}
}

( new AW_WC_AM_Internal_License_{{CLASS_VERSION}}(
	array(
		'plugin_file'           => '{{PLUGIN_FILE}}',
		'title'                 => '{{TITLE}}',
		'product_id'            => {{PRODUCT_ID}},
		'client_has_product_id' => {{CLIENT_HAS_PRODUCT_ID}},
		'api_url'               => '{{API_URL}}',
		'key_constant'          => '{{KEY_CONSTANT}}',
		'settings_page'         => '{{SETTINGS_PAGE}}',
	)
) )->register();
